/**
 * emit to subscription queries of type FindFXDeal,
 * but only if the id matches
 *
 * @param		entity	FXDeal
 */
	protected void emitFindFXDeal( FXDeal entity ) {
		LOGGER.info("handling emitFindFXDeal" );
		
	    queryUpdateEmitter.emit(FindFXDealQuery.class,
	                            query -> query.getFilter().getFXDealId().equals(entity.getFXDealId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFXDeal
	 * 
	 * @param		entity	FXDeal
	 */
	protected void emitFindAllFXDeal( FXDeal entity ) {
		LOGGER.info("handling emitFindAllFXDeal" );
		
	    queryUpdateEmitter.emit(FindAllFXDealQuery.class,
	                            query -> true,
	                            entity);
	}

